import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        Unstoppable solver = new Unstoppable();
        solver.solve(scanner, writer);
        writer.close();
    }

    static class Unstoppable {
        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            long b = in.nextLong();
            int[] a = new int[n];
            int[] c = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                c[i] = (a[i] % 2 == 0) ? 1 : -1;
            }
            long sum = 0;
            ArrayList<Integer> array = new ArrayList<>();
            for (int i = 0; i < n - 1; i++) {
                sum += c[i];
                if (sum == 0) {
                    array.add(Math.abs(a[i] - a[i + 1]));
                }
            }
            sum = 0;
            int count = 0;
            Collections.sort(array);
            for (int val : array) {
                sum += val;
                if (sum <= b) {
                    count++;
                } else {
                    break;
                }
            }
            out.println(count);
        }
    }
}
